#include "Vsingle_top.h"
#include "verilated.h"
#include <cstdio>
#include <cstdlib>
#include <cstdint>
static Vsingle_top t;static FILE*trace;static unsigned cyc=0,evs=0,checks=0,cases=0;static const char*phase="reset";
static void ck(bool x,const char*s){checks++;if(!x){fprintf(stderr,"FAIL c=%u phase=%s %s\n",cyc,phase,s);exit(1);}}
static void ev(){t.eval();evs++;ck(t.equal_on_o&&t.equal_off_o,"complete original TC/vendor/MRIF gold differs");ck(!t.off_idle_o,"defaultoff not0");if(t.quiet_o)ck(!t.tc_state_o&&!t.handler_state_o&&!t.awfifo_o&&!t.arfifo_o&&!t.wfifo_o&&!t.mrif_fifo_o&&!t.w_count_o&&t.demux_idle_o&&t.handler_idle_o,"quiet with original FIFO/FSM/debt");
 fprintf(trace,"%u,%u,%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%llx,%llx,%llx\n",cyc,evs,phase,t.clk_i,t.rst_ni,t.equal_on_o,t.equal_off_o,t.quiet_o,t.tc_state_o,t.handler_state_o,t.handler_wr_state_o,t.awfifo_o,t.arfifo_o,t.wfifo_o,t.mrif_fifo_o,t.w_count_o,t.demux_idle_o,t.handler_idle_o,t.trans_req_valid,t.trans_req_ready,t.trans_resp_valid,t.trans_resp_ready,t.trans_resp_is_mrif,t.trans_resp_error,t.tr_aw_valid,t.tr_aw_ready,t.tr_w_valid,t.tr_w_ready,t.tr_w_last,t.tr_ar_valid,t.tr_ar_ready,t.tr_b_valid,t.tr_b_ready,t.tr_r_valid,t.tr_r_ready,t.comp_aw_valid,t.comp_ar_valid,t.comp_w_valid,t.mem_ar_valid_o,t.mem_ar_ready_i,t.mem_r_valid_i,t.mem_r_ready_o,t.mem_r_last_i,t.mem_aw_valid_o,t.mem_w_valid_o,t.mem_b_valid_i,t.mem_b_ready_o,t.fault_valid_o,t.fault_ready_i,(unsigned long long)t.mem_ar_addr_o,(unsigned long long)t.mem_aw_addr_o,(unsigned long long)t.mem_w_data_o);}
static void tick(){t.clk_i=0;ev();t.clk_i=1;ev();t.clk_i=0;ev();cyc++;}
static void idle(unsigned n=4){while(n--)tick();}
template<class F>static void until(F f,const char*s){for(unsigned n=0;;n++){ev();if(f())break;ck(n<60,s);tick();}}
static void mark(const char*s){phase=s;cases++;}
static void clear(){t.fullbuffer_jobs_i=0;t.tr_aw_valid=t.tr_ar_valid=t.tr_w_valid=0;t.tr_aw_id=t.tr_ar_id=0;t.tr_aw_addr=0x1000;t.tr_ar_addr=0x2000;t.tr_aw_len=t.tr_ar_len=0;t.tr_aw_size=t.tr_ar_size=3;t.tr_aw_burst=t.tr_ar_burst=1;t.tr_aw_prot=t.tr_ar_prot=t.tr_aw_user=t.tr_ar_user=0;t.tr_aw_did=t.tr_ar_did=10;t.tr_aw_ssid_valid=t.tr_ar_ssid_valid=t.tr_aw_subid=t.tr_ar_subid=t.tr_aw_mmu_atst=t.tr_ar_mmu_atst=t.tr_aw_mmu_valid=t.tr_ar_mmu_valid=0;t.tr_w_data=0;t.tr_w_strb=255;t.tr_w_last=1;t.tr_w_user=0;t.tr_b_ready=t.tr_r_ready=1;t.comp_aw_ready=t.comp_ar_ready=t.comp_w_ready=1;t.comp_b_valid=t.comp_r_valid=0;t.comp_b_id=t.comp_r_id=0;t.comp_b_resp=t.comp_r_resp=0;t.comp_r_last=1;t.comp_r_data=0;t.trans_req_ready=0;t.trans_resp_valid=0;t.trans_resp_bank=0;t.trans_resp_error=t.trans_resp_is_mrif=t.trans_resp_ignore=0;t.trans_resp_spaddr=0x80000000;t.mem_ar_ready_i=t.mem_aw_ready_i=t.mem_w_ready_i=0;t.mem_r_valid_i=t.mem_b_valid_i=0;t.mem_r_last_i=0;t.mem_r_data_i=0;t.mem_r_resp_i=t.mem_b_resp_i=0;t.fault_ready_i=0;}
static void reset(){clear();t.rst_ni=0;idle(2);t.rst_ni=1;idle(3);ck(t.quiet_o,"initial supported single TC notquiet");}
static void aw(unsigned len=0){t.tr_aw_len=len;t.tr_aw_valid=1;until([](){return t.tr_aw_ready;},"AWready");tick();t.tr_aw_valid=0;idle(2);ck(!t.quiet_o,"queuedAW quiet");}
static void ar(unsigned len=0){t.tr_ar_len=len;t.tr_ar_valid=1;until([](){return t.tr_ar_ready;},"ARready");tick();t.tr_ar_valid=0;idle(2);ck(!t.quiet_o,"queuedAR quiet");}
static void w(bool last=true,uint64_t data=0x45){t.tr_w_valid=1;t.tr_w_last=last;t.tr_w_data=data;until([](){return t.tr_w_ready;},"Wready");tick();t.tr_w_valid=0;idle(3);}
static void translation(bool mrif=false,bool error=false,bool ignore=false){until([](){return t.trans_req_valid;},"TLrequest");ck(!t.quiet_o,"heldTLreq quiet");idle(3);t.trans_req_ready=1;tick();t.trans_req_ready=0;until([](){return t.trans_resp_ready;},"TLresponseReady");idle(3);t.trans_resp_is_mrif=mrif;t.trans_resp_error=error;t.trans_resp_ignore=ignore;t.trans_resp_valid=1;tick();t.trans_resp_valid=0;idle(6);}
static void compB(){t.comp_b_valid=1;until([](){return t.comp_b_ready;},"compBready");tick();t.comp_b_valid=0;idle();}
static void compR(bool last){t.comp_r_valid=1;t.comp_r_last=last;t.comp_r_data=0xfeed;until([](){return t.comp_r_ready;},"compRready");tick();t.comp_r_valid=0;idle();}
static void memR(bool last,uint64_t data,unsigned resp=0){t.mem_r_valid_i=1;t.mem_r_last_i=last;t.mem_r_data_i=data;t.mem_r_resp_i=resp;until([](){return t.mem_r_ready_o;},"MRIF Rready");tick();t.mem_r_valid_i=0;idle(3);}
static void memB(unsigned resp=0){t.mem_b_valid_i=1;t.mem_b_resp_i=resp;until([](){return t.mem_b_ready_o;},"MRIF Bready");tick();t.mem_b_valid_i=0;idle(3);}
static void finishWrite(bool notice=false,unsigned resp=0){until([](){return t.mem_aw_valid_o;},"MRIF AWvalid");ck(!t.quiet_o,"MRIF AWstall quiet");idle(4);if(notice)ck(t.mem_aw_addr_o==0x90000000ull&&t.mem_aw_len_o==0,"notice address/length");t.mem_aw_ready_i=1;tick();t.mem_aw_ready_i=0;until([](){return t.mem_w_valid_o;},"MRIF Wvalid");ck(t.mem_w_last_o&&t.mem_w_strb_o==(notice?15:255)&&t.mem_w_data_o==(notice?27ull:(1ull<<5)),"real MRIF W contents/strobes");idle(4);t.mem_w_ready_i=1;tick();t.mem_w_ready_i=0;idle(12);ck(!t.quiet_o,"MRIF owedB quiet");memB(resp);}
static void mrifStart(){aw();translation(true);until([](){return t.handler_state_o==1;},"real handler WAIT_INT_ID");idle(16);ck(!t.quiet_o&&!t.mem_ar_valid_o&&!t.mem_aw_valid_o&&!t.mem_w_valid_o,"WAIT_INT_ID bus-empty falselyidle");}
static void fetchStart(){w(true,0x45);until([](){return t.mem_ar_valid_o;},"realMRIF AR");ck(t.mem_ar_len_o==1,"realMRIF read not2beats");t.mem_ar_ready_i=1;tick();t.mem_ar_ready_i=0;until([](){return t.handler_state_o==3;},"real FETCH_MRIF");}
int main(int argc,char**argv){Verilated::commandArgs(argc,argv);ck(argc==2,"tracearg");trace=fopen(argv[1],"w");ck(trace,"traceopen");fprintf(trace,"cycle,eval,phase,clk,rst,equal_on,equal_off,quiet,tc_state,handler_state,wr_state,awfifo,arfifo,wfifo,mrif_fifo,w_count,demux_idle,handler_idle,tlvalid,tlready,respvalid,respready,is_mrif,resperror,awvalid,awready,wvalid,wready,wlast,arvalid,arready,bvalid,bready,rvalid,rready,cawvalid,carvalid,cwvalid,marvalid,marready,mrvalid,mrready,mrlast,mawvalid,mwvalid,mbvalid,mbready,faultvalid,faultready,maraddr,mawaddr,mwdata\n");
 mark("normal-write-FSM-IDLE-owedB-and-response-spill");reset();aw(1);translation();w(false,0x111);w(true,0x222);idle(12);ck(!t.tc_state_o&&!t.quiet_o,"early mainIDLE lost normal owedB");t.tr_b_ready=0;compB();ck(t.tr_b_valid&&!t.quiet_o,"heldnormalBspill lost");t.tr_b_ready=1;idle();ck(t.quiet_o,"normalwrite notdrain");
 mark("normal-read-nonlast-and-held-tail-spill");reset();ar(1);translation();compR(false);idle(16);ck(!t.tc_state_o&&!t.quiet_o,"nonlast gap falselyidle");t.tr_r_ready=0;compR(true);ck(t.tr_r_valid&&!t.quiet_o,"heldtailspill lost");t.tr_r_ready=1;idle();ck(t.quiet_o,"normalread notdrain");
 mark("error-write-real-SLVERR-heldB");reset();aw(1);translation(false,true);t.tr_b_ready=0;w(false);w(true);until([](){return t.tr_b_valid;},"real error B");ck(t.tr_b_resp==2&&!t.comp_aw_valid&&!t.comp_w_valid&&!t.quiet_o,"error slave path/quiet");idle(12);t.tr_b_ready=1;idle();ck(t.quiet_o,"errorslave notdrain");
 mark("ignore-write-real-OKAY-heldB");reset();aw();translation(false,false,true);t.tr_b_ready=0;w();until([](){return t.tr_b_valid;},"real ignore B");ck(t.tr_b_resp==0&&!t.mem_ar_valid_o&&!t.mem_aw_valid_o&&!t.comp_aw_valid&&!t.quiet_o,"ignore path/quiet");t.tr_b_ready=1;idle();ck(t.quiet_o,"ignore notdrain");
 mark("AWFIFO-eight-and-rejected-ninth-current-offer");reset();for(unsigned n=0;n<8;n++)aw();t.tr_aw_valid=1;idle(5);ck(!t.tr_aw_ready&&!t.quiet_o,"AWFIFO notfull or guardmissing");
 mark("ARFIFO-eight-and-rejected-ninth-current-offer");reset();for(unsigned n=0;n<8;n++)ar();t.tr_ar_valid=1;idle(5);ck(!t.tr_ar_ready&&!t.quiet_o,"ARFIFO notfull or guardmissing");
 mark("WFIFO32-W-before-address");reset();for(unsigned n=0;n<32;n++)w(n==31,0x100+n);t.tr_w_valid=1;idle(5);ck(!t.tr_w_ready&&!t.quiet_o&&!t.tc_state_o,"W FIFO notfull/guardmissing");
 mark("MRIF-invalid-interrupt-ID-original-ignore");reset();mrifStart();w(true,1u<<11);idle(8);ck(!t.handler_state_o&&!t.mem_ar_valid_o&&t.quiet_o,"invalidint originalignore notidle");
 mark("MRIF-IP-write-no-notice");reset();mrifStart();fetchStart();memR(false,0);idle(20);ck(t.handler_state_o==3&&!t.quiet_o&&!t.mem_ar_valid_o&&!t.mem_aw_valid_o&&!t.mem_w_valid_o,"real FETCH busgap falselyidle");memR(true,0);finishWrite();idle();ck(t.quiet_o,"MRIF IP-only notdrain");
 mark("MRIF-notice-and-stale-BRESP-state");reset();mrifStart();fetchStart();memR(false,0);memR(true,1ull<<5);finishWrite();finishWrite(true);idle();ck(!t.handler_state_o&&t.handler_wr_state_o==2&&t.quiet_o,"staleB_RESP incorrectlyblocks IDLE");
 mark("MRIF-R-error-fault-held-and-tail-drain");reset();mrifStart();fetchStart();memR(false,0,2);until([](){return t.fault_valid_o;},"real fault");idle(16);ck(t.fault_cause_o==264&&!t.quiet_o,"heldfault lost");memR(true,0,0);ck(!t.quiet_o,"faultready0 ignored");t.fault_ready_i=1;tick();idle();ck(t.quiet_o,"MRIFfault notdrain");
 mark("MRIF-notice-B-error-fault-held");reset();mrifStart();fetchStart();memR(false,1ull<<5);memR(true,1ull<<5);finishWrite(true,2);until([](){return t.fault_valid_o;},"noticefault");idle(16);ck(!t.quiet_o,"notice heldfault quiet");t.fault_ready_i=1;tick();idle();ck(t.quiet_o,"noticefault notdrain");
 fprintf(stdout,"PASS single cases=%u cycles=%u evals=%u checks=%u; actual original TC/FIFO/error/ignore/MRIF + independent gold; synthetic TL/DS responses; no board\n",cases,cyc,evs,checks);fclose(trace);return 0;
}
